    // ==================== HELPERS ====================
    function getColors() {
      var isDark = document.documentElement.classList.contains('theme-dark');
      return {
        isDark: isDark,
        text: isDark ? '#EDEDED' : '#0f172a',
        textSec: isDark ? '#888888' : '#64748b',
        grid: isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.07)',
        surface: isDark ? '#141414' : '#ffffff',
        accent: isDark ? '#3b82f6' : '#1d4ed8',
        negative: isDark ? '#f43f5e' : '#dc2626',
        positive: isDark ? '#10b981' : '#059669'
      };
    }

    function resetCanvas(id) {
      var old = document.getElementById(id);
      if (!old) return null;
      var parent = old.parentNode;
      var canvas = document.createElement('canvas');
      canvas.id = id;
      parent.replaceChild(canvas, old);
      return canvas;
    }

    // ==================== BUILD CHARTS ====================
    var chartsBuilt = false;
    var chartInstances = {};

    function buildCharts() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
      if (chartsBuilt) {
        Object.values(chartInstances).forEach(function(c) { try { c.destroy(); } catch(e){} });
        chartInstances = {};
      }

      var C = getColors();
      Chart.defaults.color = C.textSec;

      // ---- FED RATE LINE ----
      var fedCtx = resetCanvas('fedRateChart');
      if (fedCtx) {
        chartInstances.fed = new Chart(fedCtx, {
          type: 'line',
          data: {
            labels: FED_QUARTERS,
            datasets: [{
              label: 'Fed Funds Rate (%)',
              data: FED_RATES,
              borderColor: C.accent,
              backgroundColor: C.isDark ? 'rgba(59,130,246,0.12)' : 'rgba(29,78,216,0.08)',
              borderWidth: 2.5,
              pointRadius: 4,
              pointHoverRadius: 7,
              pointBackgroundColor: C.accent,
              tension: 0.3,
              fill: true
            }]
          },
          options: {
            responsive: true, maintainAspectRatio: false,
            plugins: {
              legend: { display: false },
              tooltip: { enabled: true, padding: 10, cornerRadius: 6,
                callbacks: { label: function(ctx) { return ' ' + ctx.parsed.y.toFixed(2) + '%'; } }
              },
              annotation: {}
            },
            scales: {
              x: { ticks: { color: C.textSec, font: { size: 11 }, maxRotation: 45, minRotation: 30 }, grid: { color: C.grid } },
              y: {
                ticks: { color: C.textSec, font: { size: 11 }, callback: function(v) { return v + '%'; } },
                grid: { color: C.grid },
                min: 0, max: 6,
                title: { display: true, text: 'Rate (%)', color: C.textSec, font: { size: 11 } }
