    // ==================== RATING TABLE ====================
    function buildRatingTable() {
      var C = getColors();

      // Periods: year-half buckets
      var periods = ['2021 H1','2021 H2','2022 H1','2022 H2','2023 H1','2023 H2','2024 H1','2024 H2'];
      var fedAtPeriod = [0.25, 0.25, 1.75, 4.5, 5.25, 5.5, 5.5, 4.5];

      function periodIndex(dateStr) {
        var parts = dateStr.split('-');
        var yr = parseInt(parts[0]), mo = parseInt(parts[1]);
        var half = mo <= 6 ? 0 : 1;
        return (yr - 2021) * 2 + half;
      }

      // Build lookup: country -> period -> action
      var lookup = {};
      COUNTRIES.forEach(function(c) { lookup[c] = {}; });
      RATING_ACTIONS.forEach(function(r) {
        var pi = periodIndex(r.date);
        if (!lookup[r.country][pi]) lookup[r.country][pi] = [];
        lookup[r.country][pi].push(r);
      });

      // Header
      var thead = document.getElementById('ratingHeader');
      if (!thead) return;
      thead.innerHTML = '';
      var th0 = document.createElement('th');
      th0.textContent = 'Country';
