      thead.appendChild(th0);
      periods.forEach(function(p, pi) {
        var th = document.createElement('th');
        th.style.cssText = 'padding:6px 4px;text-align:center;font-size:0.7rem;font-weight:600;letter-spacing:0.04em;color:' + C.textSec + ';border-bottom:1px solid ' + C.grid;
        th.innerHTML = '<div style="font-size:0.68rem;color:' + C.textSec + '">' + p + '</div><div style="font-size:0.65rem;color:' + C.accent + ';font-weight:700;">' + fedAtPeriod[pi].toFixed(2) + '%</div>';
        thead.appendChild(th);
      });

      // Fed rate row
      var tbody = document.getElementById('ratingBody');
      if (!tbody) return;
      tbody.innerHTML = '';

      // Country rows
      COUNTRIES.forEach(function(country) {
        var tr = document.createElement('tr');
        var tdName = document.createElement('td');
        tdName.style.cssText = 'padding:8px 10px;font-size:0.75rem;font-weight:600;white-space:nowrap;color:' + C.text;
        tdName.innerHTML = '<span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:' + COUNTRY_COLORS[country] + ';margin-right:6px;"></span>' + country;
        tr.appendChild(tdName);

        periods.forEach(function(p, pi) {
          var td = document.createElement('td');
          td.style.cssText = 'padding:4px;text-align:center;';
          var events = lookup[country][pi] || [];
          if (events.length === 0) {
            td.style.background = C.isDark ? '#1a1a1a' : '#f8f9fb';
            td.style.borderRadius = '4px';
            td.innerHTML = '<span style="font-size:0.62rem;color:' + C.textSec + ';opacity:0.4;">—</span>';
          } else {
            var ev = events[events.length - 1];
            var bgMap = { affirm: C.isDark?'rgba(16,185,129,0.1)':'rgba(16,185,129,0.08)', downgrade: C.isDark?'rgba(220,38,38,0.15)':'rgba(220,38,38,0.1)', upgrade: C.isDark?'rgba(59,130,246,0.12)':'rgba(59,130,246,0.08)', default: C.isDark?'rgba(180,10,10,0.25)':'rgba(180,10,10,0.15)' };
            var fgMap = { affirm: C.positive, downgrade: C.negative, upgrade: C.accent, default: '#b91c1c' };
            var labelMap = { affirm: '●', downgrade: '▼', upgrade: '▲', default: '✕' };
            var act = ev.action === 'default' ? 'default' : ev.action;
