            td.innerHTML = '<div style="font-size:0.82rem;color:' + (fgMap[act]||C.text) + ';font-weight:700;">' + (labelMap[act]||'?') + '</div><div style="font-size:0.6rem;color:' + C.textSec + ';font-weight:500;margin-top:1px;">' + ev.level + '</div>';
          }
          tr.appendChild(td);
        });
        tbody.appendChild(tr);
      });
    }

    // ==================== INIT ====================
