.kpi-strip {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px;
  margin-bottom: 48px;
}
.kpi-card {
  background: var(--surface); border: 1px solid var(--border);
  border-radius: 10px; padding: 20px 24px;
}
.kpi-label { font-size: 0.7rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-secondary); margin-bottom: 6px; }
.kpi-value { font-size: 2rem; font-weight: 700; letter-spacing: -0.04em; color: var(--text); }
.kpi-sub { font-size: 0.75rem; color: var(--text-secondary); margin-top: 4px; }

/* Fed rate overlay badge */
.fed-badge {
  display: inline-flex; align-items: center; gap: 6px;
  background: rgba(29,78,216,0.1); border: 1px solid rgba(29,78,216,0.2);
  border-radius: 6px; padding: 4px 10px;
  font-size: 0.75rem; font-weight: 600; color: var(--accent);
}

/* Animations */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}
.animate { animation: fadeInUp 0.55s ease-out both; }
.animate.delay-1 { animation-delay: 0.08s; }
.animate.delay-2 { animation-delay: 0.16s; }
.animate.delay-3 { animation-delay: 0.24s; }
.animate.delay-4 { animation-delay: 0.32s; }
.reveal { opacity: 0; transform: translateY(20px); transition: opacity 0.55s ease, transform 0.55s ease; }
.reveal.visible { opacity: 1; transform: translateY(0); }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; }
  .reveal { opacity: 1; transform: none; }
}

/* Responsive */
@media (max-width: 1100px) {
  .grid-2 { grid-template-columns: 1fr; }
  .kpi-strip { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 768px) {
  h1 { font-size: 1.8rem; }
  h2 { font-size: 1.3rem; }

